161:export function conservativeDefaultAnswer(
162:  question: string,
163:  job?: JobReach,
164:): ConservativeDefault | null {
165:  const q = question.trim();
166:  if (!q) return null;
167:
168:  // Order matters: a sponsorship question often names the United States too,
169:  // and its true answer is the opposite polarity of the authorization one.
170:  if (SPONSORSHIP_RE.test(q)) {
171:    return {
172:      answer: "Yes — I would require visa sponsorship to work in the US.",
173:      kind: "boolean",
174:      why:
175:        "No document on file says otherwise, and needing sponsorship is what " +
176:        "the absence of one means. Saying no here would assert a status the " +
177:        "candidate has not evidenced.",
178:    };
179:  }
180:  if (US_WORK_AUTHORIZATION_RE.test(q)) {
181:    return {
182:      answer: "No — I am not authorized to work in the United States.",
183:      kind: "boolean",
184:      why:
185:        "Work authorization is a document, and nothing on file evidences one. " +
186:        "The negative claims nothing; the positive would be a fabrication.",
187:    };
188:  }
189:  // Before the job-country branch: a question about the candidate's own
190:  // country names a country too, and its true answer is the opposite one.
191:  if (AUTHORIZATION_WORDS.test(q) && OWN_COUNTRY_AUTHORIZATION_RE.test(q)) {
192:    return {
193:      answer: "Yes — I am authorized to live and work in my own country.",
194:      kind: "boolean",
195:      why:
196:        "The profile says where the candidate lives, and a person may work " +
197:        "where they live. This asks about their own country, not about the " +
198:        "country this role is based in — those have different true answers.",
199:    };
200:  }
201:  if (
202:    AUTHORIZATION_WORDS.test(q) &&
203:    JOB_COUNTRY_AUTHORIZATION_RE.test(q) &&
204:    !RESIDENCE_RE.test(q)
205:  ) {
206:    const reach = whereTheWorkIs(job ?? { location: null, workCountries: [] });
207:    if (reach === "yes") {
208:      return {
209:        answer: "Yes — I am authorized to work where this role is based.",
210:        kind: "boolean",
211:        why:
212:          "The posting's reach includes a country the candidate may work in, " +
213:          "so the positive is evidenced rather than assumed.",
214:      };
215:    }
216:    return {
217:      answer:
218:        "No — I am not authorized to work in the country where this role is based.",
219:      kind: "boolean",
220:      why:
221:        reach === "no"
222:          ? "The posting is based where the candidate has no right to work."
223:          : "Where the posting is based cannot be read from it, and " +
224:            "authorization is a document. The negative claims nothing; the " +
225:            "positive would be a fabrication.",
226:    };
227:  }
228:  if (DEMOGRAPHIC_RE.test(q) || DEMOGRAPHIC_PT_ES_RE.test(q)) {
229:    return {
230:      answer: "Prefer not to say.",
231:      kind: "text",
232:      why:
233:        "Voluntary self-identification. Declining is an answer the form offers " +
234:        "and no employer may hold against it — pick the decline option as the " +
235:        "page words it.",
236:    };
237:  }
238:  return null;
